import { useState, useContext } from "react";
import { useNavigate } from "react-router-dom";
import api from "../api"; // Axios instance
import { AuthContext } from "../contexts/AuthContext";

export default function Login() {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [totp, setTotp] = useState(""); // New: TOTP input
  const [error, setError] = useState("");
  const [requireTOTP, setRequireTOTP] = useState(false);
  const { login } = useContext(AuthContext);
  const navigate = useNavigate();

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError("");

    try {
      const payload = { email, password };
      if (requireTOTP) payload.totp = totp;

      const res = await api.post("/auth/login", payload);
      const { token, user } = res.data;

      if (!user || !token) {
        setError("Invalid response from server");
        return;
      }

      // If student with TOTP enabled but TOTP not yet entered
      if (user.role === "student" && !requireTOTP && user.totpSecretEnc) {
        setRequireTOTP(true); // show OTP field
        return;
      }

      // Complete login
      login({ token, user });

      // Redirect based on role
      if (user.role === "admin") navigate("/admin-dashboard");
      else if (user.role === "comelec") navigate("/comelec-dashboard");
      else navigate("/"); // student homepage
    } catch (err) {
      console.error(err);
      if (err.response && err.response.data && err.response.data.error) {
        setError(err.response.data.error);
      } else {
        setError("Login failed. Please try again.");
      }
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-gray-100">
      <form
        onSubmit={handleSubmit}
        className="bg-white p-8 rounded-xl shadow-md w-full max-w-md"
      >
        <h2 className="text-2xl font-bold mb-6 text-gray-800">Login</h2>

        {error && <p className="text-red-600 mb-4 font-semibold">{error}</p>}

        <label className="block mb-4">
          <span className="text-gray-700">Email</span>
          <input
            type="email"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            className="mt-1 block w-full rounded-md border-gray-300 shadow-sm focus:ring focus:ring-indigo-200 focus:border-indigo-500"
            required
          />
        </label>

        <label className="block mb-4">
          <span className="text-gray-700">Password</span>
          <input
            type="password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            className="mt-1 block w-full rounded-md border-gray-300 shadow-sm focus:ring focus:ring-indigo-200 focus:border-indigo-500"
            required
          />
        </label>

        {/* OTP Field for Students */}
        {requireTOTP && (
          <label className="block mb-6">
            <span className="text-gray-700">TOTP Code</span>
            <input
              type="text"
              value={totp}
              onChange={(e) => setTotp(e.target.value)}
              className="mt-1 block w-full rounded-md border-gray-300 shadow-sm focus:ring focus:ring-indigo-200 focus:border-indigo-500"
              required
            />
          </label>
        )}

        <button
          type="submit"
          className="w-full bg-indigo-600 text-white py-2 rounded hover:bg-indigo-700 transition"
        >
          {requireTOTP ? "Verify OTP & Login" : "Login"}
        </button>

        <p className="mt-4 text-sm text-gray-600">
          Don’t have an account?{" "}
          <button
            type="button"
            className="text-indigo-600 font-semibold hover:underline"
            onClick={() => navigate("/register")}
          >
            Register
          </button>
        </p>
      </form>
    </div>
  );
}
